<?php
namespace App\Livewire;
use App\Models\SchoolEvent;use App\Models\Term;use App\Models\User;use Illuminate\Support\Facades\Auth;use Illuminate\Support\Facades\Mail;use Livewire\Attributes\Layout;use Livewire\Component;use Throwable;
#[Layout('layouts.app')] class Events extends Component {public string $termId='',$title='',$eventDate='',$type='general',$audience='all',$description='';public ?int $editingId=null;public function mount():void{$this->termId=(string)Auth::user()->school->currentTerm()?->id;$this->eventDate=now()->toDateString();}public function edit(int $id):void{$e=SchoolEvent::where('school_id',Auth::user()->school_id)->findOrFail($id);$this->editingId=$e->id;$this->termId=(string)$e->term_id;$this->title=$e->title;$this->eventDate=$e->event_date->toDateString();$this->type=$e->type;$this->audience=$e->target_audience;$this->description=$e->description??'';}public function cancel():void{$this->reset(['editingId','title','description']);$this->eventDate=now()->toDateString();$this->type='general';$this->audience='all';}public function save():void{$term=Term::where('school_id',Auth::user()->school_id)->find($this->termId);if(!$term?->isOpen()){session()->flash('error','Events can only be changed in an open term.');return;}$this->validate(['title'=>'required|string|max:255','eventDate'=>'required|date','type'=>'required|in:general,academic,staff,parent,sports,holiday','audience'=>'required|in:all,parents,staff,teachers','description'=>'nullable|string|max:2000']);$d=['school_id'=>Auth::user()->school_id,'term_id'=>$term->id,'title'=>$this->title,'event_date'=>$this->eventDate,'type'=>$this->type,'target_audience'=>$this->audience,'description'=>$this->description?:null];$this->editingId?SchoolEvent::where('school_id',Auth::user()->school_id)->findOrFail($this->editingId)->update($d):SchoolEvent::create($d);$this->cancel();session()->flash('status','Event saved.');}public function sendReminder(int $id):void{$e=SchoolEvent::where('school_id',Auth::user()->school_id)->findOrFail($id);$users=User::where('school_id',$e->school_id)->whereNotNull('email')->when($e->target_audience==='parents',fn($q)=>$q->where('role','parent'))->when($e->target_audience==='teachers',fn($q)=>$q->where('role','teacher'))->when($e->target_audience==='staff',fn($q)=>$q->whereIn('role',['admin','academic_admin','registrar','bursar','teacher']))->get();if($users->isEmpty()){session()->flash('error','No email recipients are available for this event audience.');return;}try{foreach($users as $u)Mail::raw("Reminder: {$e->title}\nDate: {$e->event_date->format('d M Y')}".($e->description?"\n\n{$e->description}":''),fn($mail)=>$mail->to($u->email)->subject('Event reminder: '.$e->title));session()->flash('status','Reminder sent to '.$users->count().' recipient(s).');}catch(Throwable $x){report($x);session()->flash('error','Email could not be sent. Check email settings and try again.');}}public function delete(int $id):void{$e=SchoolEvent::where('school_id',Auth::user()->school_id)->findOrFail($id);if(!$e->term?->isOpen()){session()->flash('error','Events in closed terms cannot be deleted.');return;}$e->delete();session()->flash('status','Event deleted.');}public function render(){$school=Auth::user()->school;return view('livewire.events',['terms'=>Term::where('school_id',$school->id)->latest('year')->get(),'events'=>SchoolEvent::with('term')->where('school_id',$school->id)->when($this->termId,fn($q)=>$q->where('term_id',$this->termId))->orderBy('event_date')->get(),'pageTitle'=>'Events']);}}
